import { PRESET_ORDER } from '../presets';
import OVERWORLD from '../overworld.json';

// The map image and node positions are generated by
// scripts/map/build_overworld.py. If this fails, a node was added to (or
// moved in) PRESET_ORDER without repainting the map: add its region to the
// script's REGIONS in ladder order and re-run it.
test('every campaign node is painted on the overworld, in ladder order', () => {
  expect(OVERWORLD.order).toEqual(PRESET_ORDER);
  for (const id of PRESET_ORDER) {
    expect(OVERWORLD.nodes).toHaveProperty(id);
  }
});
